"""Generate 500 ShareGPT knowledge samples for Lyra phase 09.3-01 batch 08-C.

Categories: tech, everyday_life, current_events.
Sub_angles: definition, mechanism, significance, comparison, example, misconception.

Inline content authored by the agent (no API calls).
"""
import json
import random
import re
import time
from pathlib import Path

ROOT = Path(__file__).resolve().parent.parent
YAML_PATH = ROOT / "templates" / "knowledge-topics-v2.yaml"
OUT_PATH = ROOT / "datasets" / "knowledge" / "raw-09.3" / "batch-08-C-knowledge.jsonl"
SEED = 0x1009031C  # 1009031C interpreted as hex per the spec id

SUB_ANGLES = ["definition", "mechanism", "significance", "comparison", "example", "misconception"]
SYSTEM_PROMPT = (
    "You are a knowledgeable assistant. Provide accurate, clear answers.\n"
    "For complex topics, break your explanation into steps.\n"
    "For simple factual questions, be concise."
)


def parse_yaml():
    with open(YAML_PATH) as f:
        text = f.read()
    sections, current, buf = {}, None, []
    for line in text.split("\n"):
        m = re.match(r"^  ([a-z_]+):\s*$", line)
        if m and m.group(1) in (
            "science", "history", "math", "tech",
            "everyday_life", "arts_and_humanities", "current_events",
        ):
            if current:
                sections[current] = buf
            current, buf = m.group(1), []
        elif current and line.startswith("    - "):
            buf.append(line[6:].strip())
    if current:
        sections[current] = buf
    return sections


# Question templates per sub_angle
QTEMPLATES = {
    "definition": [
        "What is {t}?", "Can you explain what {t} is?", "Define {t} for me.",
        "I keep hearing about {t} -- what does it actually mean?",
        "Give me a clear definition of {t}.", "What exactly is {t}?",
        "How would you describe {t} to someone unfamiliar with it?",
    ],
    "mechanism": [
        "How does {t} actually work?", "Walk me through how {t} functions.",
        "Can you explain the mechanics of {t}?", "What's happening under the hood with {t}?",
        "How does {t} operate, step by step?", "Explain the inner workings of {t}.",
        "What process drives {t}?",
    ],
    "significance": [
        "Why does {t} matter?", "What's the practical impact of {t}?",
        "Why should anyone care about {t}?", "What makes {t} important?",
        "Why is {t} a big deal?", "What's the real-world significance of {t}?",
        "Why does {t} matter in practice?",
    ],
    "comparison": [
        "How does {t} compare to similar approaches?",
        "What distinguishes {t} from related concepts?",
        "How is {t} different from its alternatives?",
        "What makes {t} unique compared to similar things?",
        "Contrast {t} with the most common alternative.",
        "How does {t} stack up against comparable options?",
    ],
    "example": [
        "Give me a concrete example of {t}.",
        "Can you show {t} in action with a real example?",
        "What's a good real-world example of {t}?",
        "Illustrate {t} with a specific case.",
        "Walk me through an example of {t}.",
        "Show me {t} applied in a practical scenario.",
    ],
    "misconception": [
        "What do people often get wrong about {t}?",
        "What's a common misconception about {t}?",
        "Where do most people misunderstand {t}?",
        "What's a myth about {t} worth correcting?",
        "What's a frequently misunderstood thing about {t}?",
        "Where does popular thinking about {t} go astray?",
    ],
}


def make_question(topic, angle, rng):
    return rng.choice(QTEMPLATES[angle]).format(t=topic)


